// ProveMixed runs every check — the generated ones and any you
// wrote — against the deliberately broken implementation it names, and
// fails if the check does not catch it.
//
//	func TestMyChecksCanFail(t *testing.T) {
//		ProveMixed(t, MixedHarness[*InMemory]{Name: "in-memory", New: NewInMemory}, myChecks)
//	}
//
// A check that always passes is indistinguishable from a working one
// until something breaks in production. This is what tells them apart:
// give each check a ProvenBy, and this proves the check can fail.
//
// A check with no ProvenBy is not ignored — it has to say why, in
// Argued. The two are held level in both directions: claiming proof
// without a broken implementation fails here, and supplying one for a
// check that claims nothing fails too.
//
// It takes the same arguments RunMixed does, and for one reason: a
// check may need a capability, and the answer is a fact about this
// interface rather than about any one implementation. The harness is
// where you write it once. A planted defect stands in for a real
// subject, so it borrows the same answer rather than being asked for one
// of its own — which nothing here could supply.
func ProveMixed(
	t *testing.T, opts ...MixedRunOpt,
) {
	t.Helper()
	var rc mixedRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := mixedNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "ProveMixed")
	s := mixedSuite(fx).With(rc.Extra...).Without(rc.Drops...)
	doors := suite.Doors(rc.Subjects...)
	defects := mixedProofs()
	for _, row := range rc.rows {
		if row.ProvenBy == nil {
			continue
		}
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveMixed: %v", err)
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveMixed: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Mixed]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	// A declined check takes its proof with it — see [prove.All].
	for _, id := range rc.Drops {
		delete(defects, id)
	}
	prove.All(t, s.Checks, defects.Answering(doors))
}

// GreenMixed runs every check — the generated ones and any you
// wrote — against an implementation that is CORRECT but different, and
// fails if a check rejects it.
//
//	func TestAnotherPolicyIsAllowed(t *testing.T) {
//		GreenMixed(t, suite.Subject[Mixed]{
//			Name: "evicts the newest", New: newNewestFirst,
//		})
//	}
//
// ProveMixed measures whether these checks can fire. This measures
// whether they fire SELECTIVELY. Nothing else here can tell a check that
// is right from one that is too strong: a check forbidding something the
// declaration permits looks exactly like a suite working, until somebody
// writes a legal implementation and it fails.
//
// The control is a real alternative, not a broken one — a different
// eviction victim, a delivery that duplicates where the contract allows
// it, a lazier evaluation behind the same boundary. Where a check
// genuinely cannot apply to your control, put its ID in the subject's
// Excused map: an excused check is skipped by name, because it yields no
// evidence either way.
//
// Same arguments as RunMixed, so the control meets the checks
// the run does — including the ones you wrote, which no caller can bind
// for themselves.
func GreenMixed(
	t *testing.T,
	control suite.Subject[Mixed],
	opts ...MixedRunOpt,
) {
	t.Helper()
	var rc mixedRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := mixedNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "GreenMixed")
	s := mixedSuite(fx).With(rc.Extra...).Without(rc.Drops...)
	// Lent the doors the run answers, so a control is refused for being
	// wrong rather than for being unwired. Answering says why.
	prove.Green(t, s.Checks,
		control.Answering(suite.Doors(rc.Subjects...)))
}

// A second version check, for the leg idioms the rows above ride. The
// harness's own covers the check format; this one covers what a model row
// does with it. Regenerate the file to clear a mismatch.
var _ = legs.CompatV1

// mixedModelRows is what this package's model tier claims.
//
// Every row here needs sequences of calls judged against something
// outside the subject, which is what separates them from the rows
// above: those settle a claim with a fixed call sequence, and these
// cannot be stated that way at all. That is also why each takes the
// Subject rather than an instance — a sequence run builds its own, and
// some of them build two.
func mixedModelRows(fx MixedFixture) []suite.Check[Mixed] {
	return []suite.Check[Mixed]{
		{
			ID:    mixedCheckIndex.Model.CRDTMerge(),
			Class: suite.ClassLaws,
			Claim: "two replicas that merge each other's state end up observably the same",
			Binds: []string{
				lawid.CRDTMerge,
			},
			Falsifiable: suite.Argued("no rule in this generator plants a defect for this claim — either nothing reaches it from shape and stamps alone, or nobody has written the rule; the defect is yours to write and this row claims no proof"),
			Strength:    suite.StrengthObserved,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertCRDTMerge(tb, sub, fx)
			},
		},
	}
}

// --- Mixed's model tier -------------------------------------------
//
// Random sequences of Mixed's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and MixedSuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — the merge relation is the claim, and every store oracle holds it inert,
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Add (writer), Items (collector)
//	Values:    the fixture pair blended with arbitrary draws
//	Not driven:
//	           Merge — takes go.thesmos.sh/testkit/conformance/corpus/iface/mixin/crdtmerge.Replica where the values pool draws string
//	Not bound:
//	           AUTO-WRITE-OBSERVABLE — instantiates at a key type no method here draws
//	           AUTO-COUNT-EQUALS-REFERENCE — the reference is the subject's own factory, so this compares a count against itself; the law legs' actions already do that, and alone it catches nondeterminism and nothing else
//	           mixed differential — the reference is the subject's own factory, whose comparison already rides each law leg's actions; alone it catches nondeterminism and nothing a second instance shares

// mixedModelValues is the value pool every value slot draws from.
//
// The fixture pair blended with arbitrary draws: the pair keeps identical
// rewrites frequent, the wide arm reaches values no fixture spells, and
// nothing in the claims licenses refusing either.
func mixedModelValues(fx MixedFixture) *model.Generator[string] {
	bodies := model.OneOf(
		model.SampledFrom([]string{fx.Item(), fx.ItemOther()}),
		model.Make[string](),
	)
	return bodies
}

// mixedModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func mixedModelActions(fx MixedFixture) []model.Action[Mixed] {
	values := mixedModelValues(fx)
	out := []model.Action[Mixed]{
		action.Writer("Add", values,
			func(ctx context.Context, s crdtmerge.Mixed, v string) error {
				return s.Add(ctx, v)
			}),
		action.Stream("Items",
			func(ctx context.Context, s crdtmerge.Mixed) ([]string, error) {
				return s.Items(ctx)
			}),
	}
	return out
}

// mixedAssertCRDTMerge binds AUTO-CRDT-MERGE over the shared sequences.
//
// One law, and the run's only oracle — see [legs.Law]
// for why the differential is off on every law leg.
func mixedAssertCRDTMerge(
	tb testing.TB,
	sub suite.Subject[Mixed],
	fx MixedFixture,
) {
	tb.Helper()
	values := mixedModelValues(fx)
	factory := func() Mixed { return sub.New(tb) }

	buildRef, tier := legs.Reference(tb, sub, func() Mixed { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Mixed { return sub.New(tb) }, buildRef,
		mixedModelActions(fx),
		[]law.Law[Mixed]{
			law.CRDTMerge[crdtmerge.Mixed, string, []string]{
				Factory: factory,
				Values:  values,
				Observe: func(rt *model.T, s crdtmerge.Mixed) []string {
					v, err := s.Items(rt.Context())
					if err != nil {
						rt.Fatalf("Observe observation failed: %v", err)
					}
					return v
				},
				Write: func(rt *model.T, s crdtmerge.Mixed, v string) error {
					return s.Add(rt.Context(), v)
				},
				Merge: func(rt *model.T, dst, src crdtmerge.Mixed) error {
					return dst.Merge(rt.Context(), src)
				},
			},
		})
}

// PropT is the property state a Prop body receives: the run's
// draws, and the failure reporting that shrinks a counterexample.
//
// An alias, so it is the engine's own type — this is here only so a
// property you write names PropT rather than obliging your test
// file to import the engine directly.
type PropT = model.T

